!-----------------------------------------------------------------------
!     THE SHELL SORTING PROCEDURE IS USED TO REORDER THE ELEMENTS OF A
!     SO THAT A(I).LE.A(I+1) FOR I=1,...,N-1. THE SAME PERMUTATIONS ARE
!     PERFORMED ON B THAT ARE PERFORMED ON A. IT IS ASSUMED THAT N.GE.1.
!-----------------------------------------------------------------------
