do 10 I = 3,10
   IF (N .LE. K(I)) GO TO 20
   IMAX = IMAX + 1
10 CONTINUE
!
!            STEPPING THROUGH THE INCREMENTS K(IMAX),...,K(1)
!
20 I = IMAX
do 40 II = 1,IMAX
   KI = K(I)
!
!             SORTING ELEMENTS THAT ARE KI POSITIONS APART
!               SO THAT A(J).LE.A(J+KI) FOR J=1,...,N-KI
!
   JMAX = N - KI
   DO J = 1,JMAX
      L = J
      LL = J + KI
      S = A(LL)
