IND(IJ) = INDX
IND(I) = IT
IT = INDX
T = X(IT)
!
! INITIALIZE L
!
5 L = J
!
! IF THE LAST ELEMENT OF THE ARRAY IS LESS THAN T,
!   INTERCHANGE IT WITH T
!
INDX = IND(J)
IF (X(INDX) .GE. T) GO TO 7
IND(IJ) = INDX
