!
INDX = IND(I)
IF (X(INDX) .LE. T) GO TO 7
IND(IJ) = INDX
IND(I) = IT
IT = INDX
T = X(IT)
GO TO 7
!
! INTERCHANGE ELEMENTS K AND L
!
6 ITT = IND(L)
IND(L) = IND(K)
IND(K) = ITT
!
! FIND AN ELEMENT IN THE UPPER PART OF THE ARRAY WHICH IS
!   NOT LARGER THAN T
!
7 L = L - 1
INDX = IND(L)
IF (X(INDX) .GT. T) GO TO 7
!
! FIND AN ELEMENT IN THE LOWER PART OF THE ARRAY WHCIH IS
