!
8 K = K + 1
INDX = IND(K)
IF (X(INDX) .LT. T) GO TO 8
!
! IF K .LE. L, INTERCHANGE ELEMENTS K AND L
!
IF (K .LE. L) GO TO 6
!
! SAVE THE UPPER AND LOWER SUBSCRIPTS OF THE PORTION OF THE
