IF (L-I .LE. J-K) GO TO 9
IL(M) = I
IU(M) = L
I = K
M = M + 1
GO TO 11
!
9 IL(M) = K
IU(M) = J
J = L
M = M + 1
GO TO 11
!
! BEGIN AGAIN ON ANOTHER UNSORTED PORTION OF THE ARRAY
!
10 M = M - 1
IF (M .EQ. 0) RETURN
I = IL(M)
J = IU(M)
!
11 IF (J-I .GE. 11) GO TO 4
IF (I .EQ. 1) GO TO 2
I = I - 1
!
! SORT ELEMENTS I+1,...,J.  NOTE THAT 1 .LE. I .LT. J AND
!   J-I .LT. 11.
!
12 I = I + 1
IF (I .EQ. J) GO TO 10
INDX = IND(I+1)
T = X(INDX)
IT = INDX
INDX = IND(I)
IF (X(INDX) .LE. T) GO TO 12
K = I
!
