IF (X .GT. 2.D0) GO TO 10
U = ((((((P7*X + P6)*X + P5)*X + P4)*X + P3)*X + &
&P2)*X + P1)*X + P0
V = ((((((Q7*X + Q6)*X + Q5)*X + Q4)*X + Q3)*X + &
&Q2)*X + Q1)*X + 1.D0
!
T = (X - 3.75D0)/(X + 3.75D0)
DERFC0 = (((((((((U/V)*T + R8)*T + R7)*T + R6)*T + R5)*T + &
&R4)*T + R3)*T + R2)*T + R1)*T + R0
RETURN
!
!                     2 .LT. X .LE. 4
