&E5)*T + E4)*T + E3)*T + E2)*T + E1)*T + E0
V = (((((((((F10*T + F9)*T + F8)*T + F7)*T + F6)*T + &
&F5)*T + F4)*T + F3)*T + F2)*T + F1)*T + 1.D0
GO TO 40
